-- Read only; no provider calls or data changes. Compare before/after, inspect deployed definitions.
SELECT p.proname,pg_get_userbyid(p.proowner) owner,p.proconfig,has_function_privilege('anon',p.oid,'execute') anon_exec,has_function_privilege('authenticated',p.oid,'execute') auth_exec,has_function_privilege('service_role',p.oid,'execute') service_exec,encode(extensions.digest(convert_to(pg_get_functiondef(p.oid),'UTF8'),'sha256'),'hex') fingerprint FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND proname IN ('slbi_submit_verified_lead','_growth_ensure_wallet','marketing_refund_ai_draft','marketing_poster_refund') ORDER BY 1;
SELECT count(*) total_businesses,count(*) FILTER(WHERE (b.rating,b.reviews_count) IS DISTINCT FROM (coalesce(r.avg_rating,0),coalesce(r.n,0))) cache_mismatches FROM public.businesses b LEFT JOIN (SELECT business_id,avg(rating) avg_rating,count(*)::integer n FROM public.reviews WHERE is_approved IS TRUE GROUP BY business_id) r ON r.business_id=b.id;
WITH l AS (SELECT user_id,period_start,sum(delta) balance FROM public.growth_credit_ledger GROUP BY 1,2) SELECT count(*) wallets,count(*) FILTER(WHERE w.credits_remaining<>coalesce(l.balance,0)) ledger_mismatches,count(*) FILTER(WHERE w.credits_remaining>greatest(0,w.credit_limit-w.credits_used)) overcap_wallets FROM public.growth_credit_wallets w LEFT JOIN l USING(user_id,period_start);
